package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.contraptions.*;
import com.simibubi.create.content.contraptions.bearing.*;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.fabricmc.fabric.api.transfer.v1.item.ItemVariant;
import net.fabricmc.fabric.api.transfer.v1.transaction.Transaction;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;

public class ControlledContraptionGameTests {
    private static final BlockPos P=new BlockPos(3,5,3),B=P.below(),T=P.south(3);
    private static ItemStack payload(){var stack=new ItemStack(Items.DIAMOND,7);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Persistent rotating inventory"));return stack;}
    private static ControlledContraptionEntity entity(GameTestHelper h)throws AssemblyException{
        h.setBlock(P,Blocks.CHEST);h.getBlockEntity(P,ChestBlockEntity.class).setItem(3,payload());var structure=new BearingContraption(false,Direction.EAST);structure.assemble(h.getLevel(),h.absolutePos(P.west()));structure.tryRemoveBlocksFromWorld(h.getLevel(),BlockPos.ZERO);
        var entity=new ControlledContraptionEntity(AllEntityTypes.CONTROLLED_CONTRAPTION,h.getLevel());entity.setContraption(structure);entity.setPos(h.absolutePos(P).getX(),h.absolutePos(P).getY(),h.absolutePos(P).getZ());return entity;
    }
    private static void machine(GameTestHelper h){h.setBlock(P,Blocks.BARREL);h.getBlockEntity(P,BarrelBlockEntity.class).setItem(0,payload());h.setBlock(B,AllBlocks.MECHANICAL_BEARING.defaultBlockState().setValue(BearingBlock.FACING,Direction.UP));h.setBlock(B.below(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(com.simibubi.create.content.kinetics.motor.CreativeMotorBlock.FACING,Direction.UP));}
    private static MechanicalBearingBlockEntity bearing(GameTestHelper h){return h.getBlockEntity(B,MechanicalBearingBlockEntity.class);}
    private static void checked(Checked body){try{body.run();}catch(RuntimeException exception){throw exception;}catch(Exception exception){throw new RuntimeException(exception);}}
    @FunctionalInterface private interface Checked{void run()throws Exception;}
    @GameTest public void entityTransformsMatchSourceContinuousRotationAndQuarterTurnPlacement(GameTestHelper h)throws Exception{
        var entity=entity(h);for(var axis:Direction.Axis.values()){entity.setRotationAxis(axis);for(float angle:new float[]{0,37,90,-90,180,359}){entity.setAngle(angle);var local=new Vec3(2.25,-.75,3.5);var global=entity.toGlobalVector(local,1);h.assertTrue(entity.toLocalVector(global,1).distanceTo(local)<1e-8,"Continuous inverse for "+axis+"/"+angle);var expected=StructureTransform.rotate(local.subtract(.5,.5,.5),angle,axis).add(.5,.5,.5).add(entity.position());h.assertTrue(global.distanceTo(expected)<1e-8,"Original pivot and signs");}}
        h.assertTrue(entity.getBoundingBox().contains(entity.position().add(.5,.5,.5)),"Broad phase contains anchored block");h.succeed();
    }
    @GameTest public void capturePhaseCannotBeGivenToMovingOwner(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.STONE);var structure=new BearingContraption(false,Direction.EAST);structure.assemble(h.getLevel(),h.absolutePos(P.west()));var entity=new ControlledContraptionEntity(AllEntityTypes.CONTROLLED_CONTRAPTION,h.getLevel());boolean refused=false;try{entity.setContraption(structure);}catch(IllegalArgumentException expected){refused=true;}h.assertTrue(refused,"World and entity cannot own a captured block simultaneously");h.assertBlockPresent(Blocks.STONE,P);h.succeed();}
    @GameTest public void nativeEntitySaveReloadPreservesMutableStorageControllerAxisAndAngle(GameTestHelper h)throws Exception{
        var entity=entity(h);entity.setRotationAxis(Direction.Axis.Z);entity.setAngle(47);entity.setControllerPos(h.absolutePos(P.west()));try(var tx=Transaction.openOuter()){entity.getContraption().getStorage().getAllItems().extract(ItemVariant.of(payload()),2,tx);tx.commit();}
        var out=TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess());entity.saveWithoutId(out);entity.getContraption().getStorage().setOwned(false);
        var restored=new ControlledContraptionEntity(AllEntityTypes.CONTROLLED_CONTRAPTION,h.getLevel());restored.load(TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess(),out.buildResult()));h.assertValueEqual(restored.getRotationAxis(),Direction.Axis.Z,"Axis restored");h.assertValueEqual(restored.getAngle(1),47f,"Continuous angle restored");h.assertValueEqual(restored.getControllerPos(),h.absolutePos(P.west()),"Relative controller restored");h.assertValueEqual(restored.getContraption().getStorage().getAllItemStorages().get(BlockPos.ZERO).getStackInSlot(3).getCount(),5,"Updated mounted contents retained");h.succeed();
    }
    @GameTest public void killReturnsOwnedBlocksAndClosesMountedAccess(GameTestHelper h)throws Exception{
        var entity=entity(h);entity.setPos(h.absolutePos(T).getX(),h.absolutePos(T).getY(),h.absolutePos(T).getZ());var old=entity.getContraption().getStorage().getAllItems();h.getLevel().addFreshEntity(entity);entity.kill(h.getLevel());h.assertTrue(entity.isRemoved(),"Killed moving entity disassembled");h.assertValueEqual(h.getBlockEntity(T,ChestBlockEntity.class).getItem(3).getCount(),7,"Owned inventory returned once");try(var tx=Transaction.openOuter()){h.assertValueEqual(old.extract(ItemVariant.of(payload()),7,tx),0L,"Removed moving owner cannot duplicate world items");}h.succeed();
    }
    @GameTest public void localOutlineRaySelectsActualRotatedBlockAndHonorsWorldObstruction(GameTestHelper h)throws Exception{
        var entity=entity(h);entity.setRotationAxis(Direction.Axis.Y);entity.setAngle(37);var center=entity.toGlobalVector(new Vec3(.5,.5,.5),1);var start=center.add(0,0,3);var end=center.add(0,0,-1);var hit=entity.rayTrace(start,end,1);h.assertTrue(hit!=null&&hit.getBlockPos().equals(BlockPos.ZERO),"Ray finds moving chest outline");h.assertTrue(entity.visibleFrom(start,end,hit,1),"No fake world blocks used for pick");h.setBlock(P.south(),Blocks.STONE);h.assertFalse(entity.visibleFrom(start,end,hit,1),"Ordinary wall in front blocks moving interaction");h.succeed();
    }
    @GameTest(maxTicks=40) public void realKineticBearingAssemblesRotatesAndStopsIntoWorld(GameTestHelper h){machine(h);h.runAfterDelay(12,()->checked(()->{var bearing=bearing(h);h.assertTrue(bearing.isRunning(),"Actual kinetic input assembles bearing");var entity=bearing.getMovedContraption();h.assertTrue(entity!=null&&entity.getAngle(1)!=0,"Real entity rotates from RPM");h.assertBlockPresent(Blocks.AIR,P);h.assertValueEqual(entity.getContraption().getStorage().getAllItemStorages().get(BlockPos.ZERO).getStackInSlot(0).getCount(),7,"Real owner contains barrel contents");h.setBlock(B.below(),Blocks.AIR);}));h.runAfterDelay(24,()->{h.assertFalse(bearing(h).isRunning(),"Default stop mode disassembles");h.assertBlockPresent(Blocks.BARREL,P);h.assertValueEqual(h.getBlockEntity(P,BarrelBlockEntity.class).getItem(0).getCount(),7,"Stopped world inventory intact");h.succeed();});}
    @GameTest(maxTicks=40) public void neverPlaceModeRetainsPausedOwnerAfterInputStops(GameTestHelper h){machine(h);bearing(h).setMovementMode(IControlContraption.RotationMode.ROTATE_NEVER_PLACE);h.runAfterDelay(12,()->{h.assertTrue(bearing(h).isRunning(),"Assembled");h.setBlock(B.below(),Blocks.AIR);});h.runAfterDelay(24,()->{h.assertTrue(bearing(h).isRunning(),"Never-place remains a moving owner when paused");h.assertBlockPresent(Blocks.AIR,P);h.assertTrue(bearing(h).getMovedContraption()!=null,"Persistent paused entity");h.assertTrue(bearing(h).disassemble(),"Manual disassembly still works");h.assertBlockPresent(Blocks.BARREL,P);h.succeed();});}
    @GameTest(maxTicks=40) public void bearingBreakRestoresContentsInsteadOfDroppingOrDiscardingOwner(GameTestHelper h){machine(h);h.runAfterDelay(12,()->{var entity=bearing(h).getMovedContraption();h.assertTrue(entity!=null,"Assembled owner");h.setBlock(B,Blocks.AIR);h.assertTrue(entity.isRemoved(),"Removing controller returns its structure");h.assertBlockPresent(Blocks.BARREL,P);h.assertValueEqual(h.getBlockEntity(P,BarrelBlockEntity.class).getItem(0).getCount(),7,"Controller removal retains inventory");h.succeed();});}
    @GameTest public void multipartSnapshotAcceptsOutOfOrderIdenticalDuplicatesAndNativeStream(GameTestHelper h){
        var data=new CompoundTag();byte[] payload=new byte[180000];new Random(17).nextBytes(payload);data.putByteArray("Bytes",payload);var parts=ContraptionDataPacket.split(9,UUID.randomUUID(),true,data);h.assertTrue(parts.size()>2,"Snapshot exceeds one native part");var assembly=new ContraptionDataPacket.Assembly(parts.getFirst());h.assertTrue(assembly.accept(parts.getFirst()).isEmpty(),"First part only");h.assertTrue(assembly.accept(parts.getFirst()).isEmpty(),"Identical duplicate does not advance count");CompoundTag decoded=null;for(int i=parts.size()-1;i>0;i--){var complete=assembly.accept(parts.get(i));if(complete.isPresent())decoded=complete.get();}h.assertTrue(data.equals(decoded),"Out of order data reassembled exactly");
        var buffer=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{ContraptionDataPacket.CODEC.encode(buffer,parts.getFirst());var packet=ContraptionDataPacket.CODEC.decode(buffer);h.assertTrue(Arrays.equals(packet.bytes(),parts.getFirst().bytes())&&packet.transfer().equals(parts.getFirst().transfer()),"Native custom payload codec");h.assertValueEqual(buffer.readableBytes(),0,"Native part consumed exactly");}finally{buffer.release();}h.succeed();
    }
    @GameTest public void invalidOrMixedSnapshotPartsCannotCrossEntityOwnership(GameTestHelper h){
        var data=new CompoundTag();data.putString("Data","Owned");var part=ContraptionDataPacket.split(9,UUID.randomUUID(),true,data).getFirst();boolean invalid=false,mixed=false;try{new ContraptionDataPacket(9,part.entityUuid(),part.transfer(),true,1,1,new byte[]{1});}catch(IllegalArgumentException expected){invalid=true;}try{new ContraptionDataPacket.Assembly(part).accept(new ContraptionDataPacket(10,UUID.randomUUID(),part.transfer(),true,0,1,part.bytes()));}catch(IllegalArgumentException expected){mixed=true;}h.assertTrue(invalid&&mixed,"Bounds and entity identity checked before accepting transfer");h.succeed();
    }
    @GameTest public void nativeQuaternionAndStructureRotationUseTheSameSignsOnAllAxes(GameTestHelper h){
        for(var axis:Direction.Axis.values())for(float angle:new float[]{37,90,-90,180}){var vector=new Vec3(1.25,-.75,2.5);var direction=Direction.get(Direction.AxisDirection.POSITIVE,axis);var nativeRotation=new org.joml.Quaternionf().rotationAxis((float)Math.toRadians(angle),direction.getStepX(),direction.getStepY(),direction.getStepZ());var actual=nativeRotation.transform(new org.joml.Vector3f((float)vector.x,(float)vector.y,(float)vector.z));var expected=StructureTransform.rotate(vector,angle,axis);h.assertTrue(new Vec3(actual.x,actual.y,actual.z).distanceTo(expected)<.00001,"Native quaternion agrees with source geometry for "+axis+"/"+angle);}h.succeed();
    }
    @GameTest public void visibleStorageDeltaRetainsPrivateContainerInteractionPositions(GameTestHelper h)throws Exception{
        var moving=entity(h);var client=Contraption.fromNBT(h.getLevel(),moving.getContraption().writeNBT(h.getLevel().registryAccess(),true),true);var storage=client.getStorage();h.assertTrue(storage.getAllItemStorages().isEmpty(),"Private chest inventory absent from rendering data");h.assertTrue(storage.getInteractablePositions().contains(BlockPos.ZERO),"Chest is still interactable");storage.handleSync(new CompoundTag(),h.getLevel().registryAccess(),client);h.assertTrue(storage.getInteractablePositions().contains(BlockPos.ZERO),"Fluid/depot deltas cannot erase a private chest interaction");h.assertTrue(storage.getAllItemStorages().isEmpty(),"Delta cannot reveal private inventory");h.succeed();
    }
    private static final class InteractionEntity extends ControlledContraptionEntity {
        private InteractionEntity(GameTestHelper h){super(AllEntityTypes.CONTROLLED_CONTRAPTION,h.getLevel());}
        @Override public boolean handlePlayerInteraction(net.minecraft.server.level.ServerPlayer player,BlockPos pos,net.minecraft.world.InteractionHand hand){return true;}
        private List<String> picks(Vec3 start,Vec3 end){return interactionPicks(start,end).stream().map(pick->pick.hit().getBlockPos()+" -> "+pick.global()).toList();}
    }
    private static InteractionEntity delayedInteraction(GameTestHelper h)throws Exception{
        h.setBlock(P,Blocks.STONE);h.setBlock(P.east(),Blocks.BARREL);h.getLevel().addFreshEntity(new com.simibubi.create.content.contraptions.glue.SuperGlueEntity(h.getLevel(),com.simibubi.create.content.contraptions.glue.SuperGlueEntity.span(h.absolutePos(P),h.absolutePos(P.east()))));var structure=new BearingContraption(false,Direction.EAST);structure.assemble(h.getLevel(),h.absolutePos(P.west()));structure.tryRemoveBlocksFromWorld(h.getLevel(),BlockPos.ZERO);var entity=new InteractionEntity(h);entity.setContraption(structure);entity.setPos(h.absolutePos(P).getX(),h.absolutePos(P).getY(),h.absolutePos(P).getZ());entity.setRotationAxis(Direction.Axis.Y);entity.setAngle(0);entity.tick();entity.setAngle(90);entity.tick();return entity;
    }
    private static net.minecraft.server.level.ServerPlayer playerLookingAtOldBarrel(GameTestHelper h){var player=(net.minecraft.server.level.ServerPlayer)h.makeMockServerPlayer(net.minecraft.world.level.GameType.SURVIVAL);var center=Vec3.atCenterOf(h.absolutePos(P.east()));player.setPos(center.x,center.y-player.getEyeHeight(),center.z+3);player.setYRot(180);player.setYHeadRot(180);player.setXRot(0);return player;}
    @GameTest public void recentTrackedPoseAllowsARealDelayedClickOnRotatingStorage(GameTestHelper h)throws Exception{
        var entity=delayedInteraction(h);var player=playerLookingAtOldBarrel(h);var start=player.getEyePosition();var end=start.add(player.getViewVector(1).scale(player.blockInteractionRange()+1));h.assertTrue(entity.rayTrace(start,end,1)==null,"Current rotated pose has already left the client's ray");boolean accepted=entity.handleInteractionPacket(player,new ContraptionInteractionPacket(entity.getId(),entity.getUUID(),new BlockPos(1,0,0),net.minecraft.world.InteractionHand.MAIN_HAND));if(!accepted){var world=ContraptionWorld.loadedWorld(h.getLevel()).clip(new net.minecraft.world.level.ClipContext(start,end,net.minecraft.world.level.ClipContext.Block.OUTLINE,net.minecraft.world.level.ClipContext.Fluid.NONE,player));Create.LOGGER.error("Delayed interaction fixture: alive={}, spectator={}, start={}, end={}, blocks={}, picks={}, world={} at {}, otherEntities={}",entity.isAlive(),player.isSpectator(),start,end,entity.getContraption().getBlocks().keySet(),entity.picks(start,end),world.getType(),world.getBlockPos(),h.getLevel().getEntitiesOfClass(AbstractContraptionEntity.class,new AABB(start,end).inflate(1)).stream().map(other->other.position().toString()).toList());}h.assertTrue(accepted,"Actual bounded historical pose accepts delayed click");h.succeed();
    }
    @GameTest public void delayedInteractionStillRejectsWallsForgedTargetsAndOutOfReachPlayers(GameTestHelper h)throws Exception{
        var entity=delayedInteraction(h);var player=playerLookingAtOldBarrel(h);var packet=new ContraptionInteractionPacket(entity.getId(),entity.getUUID(),new BlockPos(1,0,0),net.minecraft.world.InteractionHand.MAIN_HAND);
        h.assertFalse(entity.handleInteractionPacket(player,new ContraptionInteractionPacket(entity.getId(),UUID.randomUUID(),packet.localPos(),packet.hand())),"Forged entity identity rejected");h.assertFalse(entity.handleInteractionPacket(player,new ContraptionInteractionPacket(entity.getId(),entity.getUUID(),new BlockPos(99,0,0),packet.hand())),"Forged local target rejected");var position=player.position();player.setPos(position.add(0,0,10));h.assertFalse(entity.handleInteractionPacket(player,packet),"Historical pose cannot extend player reach");player.setPos(position);h.setBlock(P.east().south(),Blocks.STONE);h.assertFalse(entity.handleInteractionPacket(player,packet),"Current real wall blocks delayed interaction");h.succeed();
    }
    @GameTest public void bearingPlacementPrefersRearShaftAndShiftUsesSourceLookDirection(GameTestHelper h){
        h.setBlock(B.below(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(com.simibubi.create.content.kinetics.motor.CreativeMotorBlock.FACING,Direction.UP));var player=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(AllBlocks.MECHANICAL_BEARING));player.setYRot(90);player.setXRot(0);var hit=new BlockHitResult(Vec3.atCenterOf(h.absolutePos(B.below())).add(0,.5,0),Direction.UP,h.absolutePos(B.below()),false);var context=new net.minecraft.world.item.context.BlockPlaceContext(new net.minecraft.world.item.context.UseOnContext(player,net.minecraft.world.InteractionHand.MAIN_HAND,hit));h.assertValueEqual(AllBlocks.MECHANICAL_BEARING.getStateForPlacement(context).getValue(BearingBlock.FACING),Direction.UP,"Rear shaft determines preferred facing");player.setShiftKeyDown(true);var shifted=new net.minecraft.world.item.context.BlockPlaceContext(new net.minecraft.world.item.context.UseOnContext(player,net.minecraft.world.InteractionHand.MAIN_HAND,hit));h.assertValueEqual(AllBlocks.MECHANICAL_BEARING.getStateForPlacement(shifted).getValue(BearingBlock.FACING),shifted.getNearestLookingDirection(),"Shift bypasses preferred shaft with source facing convention");h.succeed();
    }
}
